import java.util.*; import java.io.*; public class Main { private static Map<Long, Long> memo = new HashMap<>(); private static long[] smallMemo = new long[1000001]; public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line; while ((line = br.readLine()) != null && !line.isEmpty()) { long n = Long.parseLong(line.trim()); System.out.println(solve(n)); } } private static long solve(long n) { if (n < 1000001) { if (smallMemo[(int) n] != 0) return smallMemo[(int) n]; } else { if (memo.containsKey(n)) return memo.get(n); } if (n == 0) return 0; long res = Math.max(n, solve(n / 2) + solve(n / 3) + solve(n / 4)); if (n < 1000001) { smallMemo[(int) n] = res; } else { memo.put(n, res); } return res; } }